import { spawnSync } from 'node:child_process';
import { mkdirSync, rmSync } from 'node:fs';
const python = process.platform === 'win32' ? 'python' : 'python3';
const rustBinary = process.platform === 'win32' ? '.galaxy-rust-test.exe' : '.galaxy-rust-test';
const javaOut = '.galaxy-java-classes';
const commands = [
  [process.execPath, ['--test', 'test/vue-client.test.mjs', 'test/angular-pricing.test.mjs', 'test/vite-inventory.test.mjs']],
  [python, ['-m', 'unittest', 'backend/test_cms_service.py']],
  ['rustc', ['--test', 'rust/pricing.rs', '-o', rustBinary]],
  [process.platform === 'win32' ? rustBinary : `./${rustBinary}`, []],
  ['javac', ['-d', javaOut, 'java/src/InventoryService.java', 'java/test/InventoryServiceTest.java']],
  ['java', ['-cp', javaOut, 'InventoryServiceTest']]
];
try {
  mkdirSync(javaOut, { recursive: true });
  for (const [command, args] of commands) {
    const result = spawnSync(command, args, { encoding: 'utf8', stdio: 'inherit', shell: false });
    if (result.error) throw result.error;
    if (result.status !== 0) throw new Error(`${command} failed with exit code ${result.status ?? 1}`);
  }
} finally {
  rmSync(rustBinary, { force: true });
  rmSync(javaOut, { recursive: true, force: true });
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { createInventoryClient } from '../web/vite/inventory-client.js';

test('Vite-facing inventory adapter honors validation and HTTP contract', async () => {
  const calls = [];
  const http = { post: async (...args) => { calls.push(args); return { data: { remaining: 3 } }; } };
  const client = createInventoryClient(http);
  assert.deepEqual(await client.reserve('lamp', 2), { remaining: 3 });
  assert.deepEqual(calls, [['/api/inventory/reservations', { sku: 'lamp', quantity: 2 }]]);
  await assert.rejects(async () => client.reserve('lamp', 0), /quantity/i);
});

import java.util.Map;

public final class InventoryServiceTest {
  public static void main(String[] args) {
    InventoryService service = new InventoryService(Map.of("lamp", 5));
    if (service.reserve("lamp", 2) != 3 || service.stockOf("lamp") != 3) throw new AssertionError("reservation failed");
    expectFailure(() -> service.reserve("lamp", 4));
    expectFailure(() -> service.reserve("missing", 1));
    expectFailure(() -> service.reserve("lamp", 0));
    System.out.println("InventoryServiceTest passed");
  }
  private static void expectFailure(Runnable operation) {
    try { operation.run(); throw new AssertionError("expected failure"); }
    catch (IllegalArgumentException expected) { }
  }
}
